        "Chang C. Tsuei",
        "Dale J. Van Harlingen",
        "John R. Kirtley"
      ],
      "assessment": {
        "nobel_worthiness": "Phase-sensitive experiments supplied compelling evidence for d-wave pairing in cuprates, clarifying the symmetry of the order parameter in a major class of unconventional superconductors.",
        "attribution": "Tsuei and Kirtley led influential phase-sensitive tests; Van Harlingen's earlier interferometry work was an important foundation for this experimental approach.",
        "maturity": "The evidence has accumulated across complementary measurements and remains central to the accepted picture of cuprate pairing.",
        "uncertainties": [
          "The specific credited contribution of each person to the experimental proof should be separated from earlier methodological work."
        ]
      }
    },
